export const SUBS: { from: number; to: number; text: string }[] = [{"from": 36, "to": 87, "text": "अगर आप एक YouTube Creator हो,"}, {"from": 88, "to": 203, "text": "तो आप जानते हो कि एक अच्छी वीडियो बनाने में कितनी मेहनत लगती है।"}, {"from": 216, "to": 348, "text": "सबसे पहले एक अच्छा topic ढूँढना पड़ता है। फिर research करनी होती है,"}, {"from": 349, "to": 464, "text": "script लिखनी होती है, title और thumbnail तैयार करना होता है,"}, {"from": 465, "to": 604, "text": "और वीडियो publish करने के बाद उसकी performance भी analyze करनी पड़ती है।"}, {"from": 618, "to": 763, "text": "लेकिन सोचिए, अगर आपके पास एक ऐसा AI assistant हो जो आपके चैनल को समझता हो,"}, {"from": 764, "to": 814, "text": "आपकी audience को जानता हो,"}, {"from": 815, "to": 956, "text": "और आपकी content creation journey के अलग-अलग हिस्सों में आपकी मदद कर सके?"}, {"from": 969, "to": 1055, "text": "यहीं पर Claude AI आपके लिए काफी useful हो सकता है।"}, {"from": 1069, "to": 1176, "text": "आज हम सीखेंगे कि Claude को एक personal YouTube content assistant की तरह कैसे"}, {"from": 1177, "to": 1196, "text": "setup करना है।"}, {"from": 1209, "to": 1337, "text": "हम Projects, custom instructions, reference files, Skills, video ideas,"}, {"from": 1338, "to": 1458, "text": "thumbnail concepts और analytics workflows को step by step समझेंगे।"}, {"from": 1471, "to": 1548, "text": "और सबसे अच्छी बात, हम केवल theory नहीं देखेंगे।"}, {"from": 1549, "to": 1635, "text": "हर important feature का practical example भी समझेंगे।"}, {"from": 1669, "to": 1768, "text": "सबसे पहले समझते हैं कि Claude AI क्या है।"}, {"from": 1782, "to": 1907, "text": "Claude एक AI assistant है, जिसे Anthropic ने develop किया है।"}, {"from": 1920, "to": 2019, "text": "इसकी मदद से आप लिख सकते हो, जानकारी को समझ सकते हो,"}, {"from": 2020, "to": 2162, "text": "documents analyze कर सकते हो और अपने creative कामों में सहायता ले सकते हो।"}, {"from": 2176, "to": 2303, "text": "एक YouTube Creator के लिए Claude का सबसे बड़ा फायदा सिर्फ script लिखना नहीं"}, {"from": 2304, "to": 2308, "text": "है।"}, {"from": 2321, "to": 2460, "text": "असली फायदा तब मिलता है जब आप इसे अपने चैनल से जुड़ा सही context देते हो।"}, {"from": 2474, "to": 2550, "text": "मान लीजिए आप technology videos बनाते हो।"}, {"from": 2551, "to": 2681, "text": "आपका बोलने का style Hindi-Hinglish है, आपकी audience beginners हैं,"}, {"from": 2682, "to": 2778, "text": "और आप आसान examples के साथ topics explain करते हो।"}, {"from": 2792, "to": 2862, "text": "अगर Claude को ये सारी बातें मालूम हों,"}, {"from": 2863, "to": 2967, "text": "तो वह आपके लिए ज्यादा relevant content तैयार कर सकता है।"}, {"from": 2980, "to": 3088, "text": "इसीलिए हमें सबसे पहले AI को अपने चैनल के बारे में सिखाना होगा।"}, {"from": 3122, "to": 3196, "text": "अब मान लीजिए आपको एक नई वीडियो की script लिखवानी है।"}, {"from": 3210, "to": 3329, "text": "Normally आपको AI को बताना पड़ता है कि आपके चैनल का niche क्या है,"}, {"from": 3330, "to": 3441, "text": "audience कैसी है, language क्या है, वीडियो कितनी लंबी चाहिए,"}, {"from": 3442, "to": 3511, "text": "और आपका writing style कैसा होना चाहिए।"}, {"from": 3525, "to": 3582, "text": "अगर आप बार-बार अलग-अलग काम करते हो,"}, {"from": 3583, "to": 3684, "text": "तो यह सारी instructions repeat करना time-consuming हो सकता है।"}, {"from": 3697, "to": 3810, "text": "इसी problem को आसान बनाने के लिए Claude में Projects का इस्तेमाल किया जा सकता"}, {"from": 3811, "to": 3879, "text": "है, जहाँ यह feature आपके account पर उपलब्ध हो।"}, {"from": 3892, "to": 4019, "text": "Project एक dedicated workspace होता है जिसमें आप किसी खास काम के लिए relevant"}, {"from": 4020, "to": 4112, "text": "instructions और reference materials organize कर सकते हो।"}, {"from": 4125, "to": 4227, "text": "एक YouTube Creator अपने चैनल के लिए अलग Project बना सकता है।"}, {"from": 4241, "to": 4372, "text": "उसके बाद उसी workspace में नई chats शुरू करके channel-related tasks कर सकता"}, {"from": 4373, "to": 4377, "text": "है।"}, {"from": 4391, "to": 4541, "text": "इस तरह आप बार-बार शुरुआत से पूरी जानकारी लिखने की जरूरत कम कर सकते हो।"}, {"from": 4554, "to": 4666, "text": "लेकिन याद रखिए, AI का output हमेशा review करना जरूरी है,"}, {"from": 4667, "to": 4785, "text": "क्योंकि saved context होने के बाद भी AI गलतियाँ कर सकता है।"}, {"from": 4819, "to": 4863, "text": "अब practical setup समझते हैं।"}, {"from": 4876, "to": 5004, "text": "सबसे पहले Claude के Projects section में जाइए और नया Project create कीजिए।"}, {"from": 5018, "to": 5134, "text": "हम इस example में Project का नाम रखेंगे YouTube Content Assistant।"}, {"from": 5147, "to": 5243, "text": "इसके बाद आपको अपने Project का purpose clearly define करना है।"}, {"from": 5257, "to": 5295, "text": "जैसे, Help me research,"}, {"from": 5296, "to": 5401, "text": "plan and create high-quality YouTube content for my audience."}, {"from": 5414, "to": 5493, "text": "अब सबसे important हिस्सा है Project Instructions."}, {"from": 5506, "to": 5620, "text": "यहाँ आप Claude को बताएँगे कि वह आपके लिए किस role में काम करेगा।"}, {"from": 5633, "to": 5763, "text": "उदाहरण के लिए, तुम मेरे YouTube content strategy assistant हो।"}, {"from": 5764, "to": 5885, "text": "तुम्हारा काम है मुझे engaging scripts, better video ideas,"}, {"from": 5886, "to": 6009, "text": "compelling titles और thumbnail concepts बनाने में मदद करना।"}, {"from": 6022, "to": 6105, "text": "इसके साथ आपको अपने चैनल का niche, audience,"}, {"from": 6106, "to": 6199, "text": "language और writing style भी specify करना चाहिए।"}, {"from": 6213, "to": 6283, "text": "आप जितना clear और useful context दोगे,"}, {"from": 6284, "to": 6370, "text": "Claude के लिए आपके goals समझना उतना आसान होगा।"}, {"from": 6404, "to": 6496, "text": "Project Instructions में केवल चैनल का नाम लिखना काफी नहीं है।"}, {"from": 6509, "to": 6603, "text": "आपको अपनी content identity भी explain करनी चाहिए।"}, {"from": 6617, "to": 6692, "text": "सबसे पहले बताइए कि आपका ideal viewer कौन है।"}, {"from": 6706, "to": 6856, "text": "उसे किस तरह की problems face करनी पड़ती हैं? वह आपके वीडियो क्यों देखता है?"}, {"from": 6857, "to": 6945, "text": "और वीडियो देखने के बाद उसे क्या सीखना चाहिए?"}, {"from": 6958, "to": 7019, "text": "इसके बाद अपनी brand voice define कीजिए।"}, {"from": 7033, "to": 7150, "text": "आप educational content बनाते हो, entertaining videos बनाते हो,"}, {"from": 7151, "to": 7231, "text": "या documentary-style storytelling करते हो?"}, {"from": 7244, "to": 7326, "text": "आपकी भाषा formal होनी चाहिए या conversational?"}, {"from": 7327, "to": 7426, "text": "आप छोटे sentences पसंद करते हो या detailed explanation?"}, {"from": 7439, "to": 7539, "text": "इसके बाद अपने content creation workflow के बारे में बताइए।"}, {"from": 7553, "to": 7699, "text": "आपको research में मदद चाहिए, scriptwriting में, title generation में,"}, {"from": 7700, "to": 7754, "text": "या analytics analysis में?"}, {"from": 7768, "to": 7884, "text": "यह सारी information Claude को आपके लिए ज्यादा useful creative partner बनने में"}, {"from": 7885, "to": 7907, "text": "मदद कर सकती है।"}, {"from": 7941, "to": 8034, "text": "अब आता है एक बहुत useful step, reference files add करना।"}, {"from": 8048, "to": 8140, "text": "मान लीजिए आपने पिछले कुछ महीनों में कई YouTube videos upload की हैं।"}, {"from": 8154, "to": 8262, "text": "आप अपने अच्छे perform करने वाले videos की scripts को reference के तौर पर"}, {"from": 8263, "to": 8374, "text": "Project में add कर सकते हो, अगर आपके account में file upload available है।"}, {"from": 8388, "to": 8459, "text": "इससे Claude आपके writing patterns,"}, {"from": 8460, "to": 8600, "text": "explanations और content structure को better understand कर सकता है।"}, {"from": 8614, "to": 8720, "text": "इसके अलावा आप YouTube Studio से analytics data भी export कर सकते हो।"}, {"from": 8734, "to": 8805, "text": "YouTube Studio खोलिए, Analytics में जाइए,"}, {"from": 8806, "to": 8920, "text": "और जरूरत के अनुसार Advanced Mode में अपनी date range select कीजिए।"}, {"from": 8934, "to": 9048, "text": "फिर उपलब्ध export option का इस्तेमाल करके CSV data download कीजिए।"}, {"from": 9062, "to": 9129, "text": "इस data में video titles, views, impressions,"}, {"from": 9130, "to": 9201, "text": "click-through rate और दूसरे metrics हो सकते हैं।"}, {"from": 9214, "to": 9286, "text": "लेकिन केवल वही data share कीजिए जो जरूरी हो।"}, {"from": 9287, "to": 9402, "text": "Sensitive information और private details को पहले remove करना बेहतर है।"}, {"from": 9416, "to": 9475, "text": "अब आपके पास channel instructions,"}, {"from": 9476, "to": 9565, "text": "sample scripts और analytics data तीनों तैयार हैं।"}, {"from": 9599, "to": 9680, "text": "अब देखते हैं कि यह setup practical काम कैसे कर सकता है।"}, {"from": 9693, "to": 9785, "text": "अपने YouTube Project के अंदर नई chat शुरू कीजिए।"}, {"from": 9799, "to": 9834, "text": "और Claude से पूछिए,"}, {"from": 9835, "to": 9976, "text": "मेरे चैनल की audience और पिछले वीडियो topics के आधार पर पाँच नए video ideas"}, {"from": 9977, "to": 9998, "text": "suggest करो।"}, {"from": 10012, "to": 10125, "text": "Claude उपलब्ध project context और reference material को इस्तेमाल करके ideas"}, {"from": 10126, "to": 10151, "text": "तैयार कर सकता है।"}, {"from": 10164, "to": 10202, "text": "लेकिन यहाँ एक जरूरी बात है।"}, {"from": 10216, "to": 10375, "text": "AI से मिले ideas automatically trending या guaranteed successful नहीं होते।"}, {"from": 10389, "to": 10437, "text": "आपको उन्हें audience demand,"}, {"from": 10438, "to": 10560, "text": "search interest और अपने channel goals के आधार पर evaluate करना चाहिए।"}, {"from": 10574, "to": 10645, "text": "अब किसी एक topic को select करके बोलिए,"}, {"from": 10646, "to": 10782, "text": "इस idea के लिए एक engaging introduction और detailed script outline बनाओ।"}, {"from": 10796, "to": 10864, "text": "आप चाहो तो उसे examples add करने,"}, {"from": 10865, "to": 11013, "text": "भाषा आसान करने और वीडियो को ज्यादा engaging बनाने के लिए भी कह सकते हो।"}, {"from": 11026, "to": 11125, "text": "इस तरह Claude आपके research और planning process में एक useful assistant बन"}, {"from": 11126, "to": 11136, "text": "सकता है।"}, {"from": 11170, "to": 11290, "text": "अब बात करते हैं Claude के एक और interesting concept की, Skills."}, {"from": 11304, "to": 11413, "text": "Skills ऐसे reusable instructions और resources हो सकते हैं जो किसी particular"}, {"from": 11414, "to": 11485, "text": "task को repeatable तरीके से करने में मदद करते हैं।"}, {"from": 11499, "to": 11589, "text": "मान लीजिए आपको हर हफ्ते YouTube titles generate करने होते हैं।"}, {"from": 11603, "to": 11720, "text": "हर बार एक लंबा prompt लिखने के बजाय आप एक structured workflow तैयार कर सकते"}, {"from": 11721, "to": 11725, "text": "हो।"}, {"from": 11739, "to": 11849, "text": "यह workflow समझा सकता है कि अच्छे title में clarity, curiosity,"}, {"from": 11850, "to": 11941, "text": "accuracy और audience relevance कैसे balance करनी है।"}, {"from": 11955, "to": 12018, "text": "इसी तरह आप script review, intro writing,"}, {"from": 12019, "to": 12140, "text": "thumbnail brainstorming और channel analysis के लिए भी reusable instructions"}, {"from": 12141, "to": 12160, "text": "बना सकते हो।"}, {"from": 12173, "to": 12269, "text": "ध्यान रखिए, Skills की availability आपके Claude product,"}, {"from": 12270, "to": 12341, "text": "plan और environment पर depend कर सकती है।"}, {"from": 12354, "to": 12472, "text": "हम इस tutorial में इनके practical concepts को समझेंगे और दिखाएँगे कि एक"}, {"from": 12473, "to": 12568, "text": "creator इन्हें अपने workflow में कैसे organize कर सकता है।"}, {"from": 12602, "to": 12725, "text": "मान लीजिए आपको जानना है कि आपके चैनल पर कौन से videos अच्छा perform कर रहे हैं"}, {"from": 12726, "to": 12792, "text": "और किन videos को improve करने की जरूरत है।"}, {"from": 12805, "to": 12905, "text": "इसके लिए आप YouTube Analytics CSV को analyze करवा सकते हो।"}, {"from": 12919, "to": 13048, "text": "एक structured reporting workflow Claude को बता सकता है कि views, impressions,"}, {"from": 13049, "to": 13158, "text": "CTR, watch time और subscriber performance कैसे summarize करनी है।"}, {"from": 13172, "to": 13194, "text": "उदाहरण के लिए,"}, {"from": 13195, "to": 13318, "text": "अगर किसी वीडियो को impressions मिल रहे हैं लेकिन click-through rate कम है,"}, {"from": 13319, "to": 13419, "text": "तो उसके title और thumbnail को review करना उपयोगी हो सकता है।"}, {"from": 13432, "to": 13546, "text": "लेकिन सिर्फ CTR देखकर पूरी performance का फैसला नहीं करना चाहिए। Topic,"}, {"from": 13547, "to": 13637, "text": "traffic source, audience और video age भी महत्वपूर्ण हैं।"}, {"from": 13650, "to": 13738, "text": "इसी तरह आप देख सकते हो कि किन videos से subscribers आए,"}, {"from": 13739, "to": 13816, "text": "किन topics पर viewers ने ज्यादा interest दिखाया,"}, {"from": 13817, "to": 13882, "text": "और कहाँ improvement के opportunities हैं।"}, {"from": 13895, "to": 14000, "text": "इस पूरी information से एक readable report card तैयार किया जा सकता है।"}, {"from": 14013, "to": 14089, "text": "अच्छी analytics केवल numbers नहीं बताती,"}, {"from": 14090, "to": 14174, "text": "बल्कि better decisions लेने में मदद करती है।"}, {"from": 14208, "to": 14306, "text": "अब एक practical example देखते हैं, Title Writer."}, {"from": 14320, "to": 14428, "text": "एक अच्छा YouTube title viewer को यह समझाने में मदद करता है कि वीडियो उसके लिए"}, {"from": 14429, "to": 14454, "text": "क्यों relevant है।"}, {"from": 14467, "to": 14568, "text": "हम Claude को instruction दे सकते हैं कि किसी भी topic के लिए पाँच या छह"}, {"from": 14569, "to": 14620, "text": "different title options generate करो।"}, {"from": 14634, "to": 14686, "text": "हर title clear हो, interesting हो,"}, {"from": 14687, "to": 14773, "text": "और वीडियो के actual content को accurately represent करे।"}, {"from": 14787, "to": 14877, "text": "साथ ही Claude से पूछ सकते हैं कि किस title में curiosity है,"}, {"from": 14878, "to": 14995, "text": "किसमें specific benefit है, और किसमें search-friendly wording इस्तेमाल हुई है।"}, {"from": 15008, "to": 15116, "text": "फिर हम इन titles को compare करके सबसे suitable option select कर सकते हैं।"}, {"from": 15129, "to": 15239, "text": "आप Claude से यह भी कह सकते हो कि title को थोड़ा छोटा करो,"}, {"from": 15240, "to": 15366, "text": "language ज्यादा natural बनाओ, या unnecessary clickbait remove करो।"}, {"from": 15380, "to": 15493, "text": "Repeated testing और feedback से आपका workflow ज्यादा consistent हो सकता है।"}, {"from": 15507, "to": 15531, "text": "लेकिन याद रखिए,"}, {"from": 15532, "to": 15654, "text": "AI-generated scores या predictions actual YouTube performance की guarantee"}, {"from": 15655, "to": 15669, "text": "नहीं हैं।"}, {"from": 15703, "to": 15816, "text": "अब बात करते हैं दो बहुत important content creation elements की,"}, {"from": 15817, "to": 15863, "text": "intro hooks और thumbnails."}, {"from": 15877, "to": 15986, "text": "YouTube पर शुरुआत के कुछ seconds viewer को यह समझाने के लिए महत्वपूर्ण होते"}, {"from": 15987, "to": 16039, "text": "हैं कि वीडियो आगे क्यों देखनी चाहिए।"}, {"from": 16053, "to": 16171, "text": "Claude की मदद से आप एक ही topic के लिए different opening hooks brainstorm कर"}, {"from": 16172, "to": 16184, "text": "सकते हो।"}, {"from": 16197, "to": 16290, "text": "जैसे एक question-based hook, एक surprising observation,"}, {"from": 16291, "to": 16405, "text": "एक problem-solution opening, या एक direct educational introduction."}, {"from": 16418, "to": 16527, "text": "फिर आप अपने चैनल की style और audience के हिसाब से सबसे natural hook choose कर"}, {"from": 16528, "to": 16539, "text": "सकते हो।"}, {"from": 16552, "to": 16608, "text": "इसके बाद आता है Thumbnail Ideation."}, {"from": 16622, "to": 16743, "text": "यहाँ आप Claude को अपना topic दे सकते हो और उससे multiple thumbnail concepts"}, {"from": 16744, "to": 16778, "text": "generate करवा सकते हो।"}, {"from": 16792, "to": 16889, "text": "हर concept के साथ आप visual composition, background colors,"}, {"from": 16890, "to": 16994, "text": "main subject और short thumbnail text के suggestions ले सकते हो।"}, {"from": 17007, "to": 17085, "text": "लेकिन final thumbnail बनाते समय readability,"}, {"from": 17086, "to": 17174, "text": "accuracy और visual clarity का ध्यान रखना जरूरी है।"}, {"from": 17188, "to": 17233, "text": "AI से ideas लेना useful है,"}, {"from": 17234, "to": 17328, "text": "लेकिन final creative judgment creator का ही होना चाहिए।"}, {"from": 17362, "to": 17430, "text": "अब इन सारे features को एक साथ जोड़कर देखते हैं।"}, {"from": 17444, "to": 17538, "text": "सबसे पहले आप अपने channel के लिए dedicated Project setup करते हो।"}, {"from": 17552, "to": 17630, "text": "फिर उसमें audience information, brand voice,"}, {"from": 17631, "to": 17738, "text": "writing preferences और relevant reference files add करते हो।"}, {"from": 17752, "to": 17843, "text": "इसके बाद Claude से नए video topics brainstorm करवा सकते हो।"}, {"from": 17857, "to": 17924, "text": "Selected topic के लिए research outline,"}, {"from": 17925, "to": 18027, "text": "engaging introduction और script structure तैयार कर सकते हो।"}, {"from": 18041, "to": 18138, "text": "Title Writer workflow से multiple titles compare कर सकते हो।"}, {"from": 18151, "to": 18234, "text": "Thumbnail Ideation से visual concepts explore कर सकते हो।"}, {"from": 18248, "to": 18357, "text": "और वीडियो publish होने के बाद analytics data की मदद से समझ सकते हो कि क्या"}, {"from": 18358, "to": 18432, "text": "अच्छा perform हुआ और क्या improve किया जा सकता है।"}, {"from": 18446, "to": 18555, "text": "इस तरह आपका workflow एक organized system बन जाता है।"}, {"from": 18569, "to": 18694, "text": "Claude आपकी creativity को replace नहीं करता। वह planning, drafting,"}, {"from": 18695, "to": 18827, "text": "analysis और repetitive tasks को manage करने में आपकी सहायता कर सकता है।"}, {"from": 18861, "to": 18982, "text": "तो अब आप समझ गए होंगे कि Claude AI को सिर्फ एक normal chatbot की तरह इस्तेमाल"}, {"from": 18983, "to": 19088, "text": "करने के बजाय एक structured content assistant कैसे बनाया जा सकता है।"}, {"from": 19101, "to": 19185, "text": "Projects से आप relevant context organize कर सकते हो।"}, {"from": 19198, "to": 19322, "text": "Skills और reusable instructions से अपने repeated tasks को streamline कर सकते"}, {"from": 19323, "to": 19327, "text": "हो।"}, {"from": 19341, "to": 19469, "text": "और analytics के साथ AI की मदद लेकर अपने content decisions को ज्यादा informed"}, {"from": 19470, "to": 19489, "text": "बना सकते हो।"}, {"from": 19503, "to": 19629, "text": "सबसे important बात, हमेशा अपने content को review करो, facts verify करो,"}, {"from": 19630, "to": 19696, "text": "और अपनी original creativity बनाए रखो।"}, {"from": 19709, "to": 19777, "text": "अगर आपको यह tutorial useful लगा,"}, {"from": 19778, "to": 19937, "text": "तो वीडियो को like कीजिए और ऐसे ही AI tools और YouTube creation tutorials के"}, {"from": 19938, "to": 19997, "text": "लिए चैनल को subscribe कीजिए।"}, {"from": 20010, "to": 20064, "text": "मिलते हैं अगली वीडियो में। Thank you!"}];
